mapper.select:
SELECT l.id AS id, l.account_id AS account_id, l.user_id AS user_id, l.sync_type AS sync_type, l.sync_result AS sync_result, l.commit_count AS commit_count, l.cost_ms AS cost_ms, l.error_msg AS error_msg, l.create_time AS create_time FROM repo_sync_log l WHERE l.deleted = 0 AND l.account_id IN
#{accountId}
AND l.id = (SELECT l2.id FROM repo_sync_log l2 WHERE l2.deleted = 0 AND l2.account_id = l.account_id ORDER BY l2.create_time DESC, l2.id DESC LIMIT 1)
